// Code node "Queue bookings" (run once for all items).
// Input: appointments PracticeQ reports as updated since yesterday (one item each, or one
// empty item when there are none). Output: one item per client whose summary is due now.
//
// A client enters the queue when a new open appointment is booked for them. Any further
// change to that client's appointments while they wait (another booking, a reschedule, a
// cancellation) pushes the send time back, so the email goes out once the schedule has been
// quiet for `bufferMinutes`. Edits to clients who are not waiting (marking a visit attended,
// invoicing) never trigger an email.
const s = $('Settings').first().json;
const state = $getWorkflowStaticData('global');
const OPEN = ['Confirmed', 'WaitingConfirmation'];
const now = Date.now();
const bufferMs = Number(s.bufferMinutes) * 60000;
state.pending = state.pending || {};

const rows = $input.all().map((i) => i.json).filter((r) => r && r.Id);

if (state.cursor === undefined) {
  // First run: watch from now on, never email for changes made before the switch-on.
  state.cursor = rows.reduce((m, r) => Math.max(m, Number(r.LastModified) || 0), now);
  return [];
}

const since = state.cursor;
let cursor = since;
for (const r of rows) {
  const modified = Number(r.LastModified) || 0;
  if (modified <= since) continue;
  cursor = Math.max(cursor, modified);

  const key = String(r.ClientId);
  const waiting = state.pending[key];
  const newBooking = Number(r.DateCreated) > since && OPEN.includes(r.Status) && Number(r.StartDate) > now;
  if (!waiting && !newBooking) continue;

  state.pending[key] = {
    clientId: r.ClientId,
    email: r.ClientEmail || (waiting && waiting.email) || '',
    name: r.ClientName || (waiting && waiting.name) || '',
    dueAt: Math.max(waiting ? waiting.dueAt : 0, modified + bufferMs),
    attempts: waiting ? waiting.attempts : 0,
  };
}
state.cursor = cursor;

const due = [];
for (const [key, p] of Object.entries(state.pending)) {
  if (p.dueAt <= now) {
    due.push(p);
    delete state.pending[key];
  }
}
return due.map((p) => ({ json: p }));

// Code node "Build PDFs" (run once for all items).
// Input: every appointment from today on for each due client (from "Get upcoming").
// Output: one item per PDF to upload, with the PracticeQ client to upload to and the PDF as
// binary property `data`. The PDF is written by hand (Helvetica, US Letter) so the workflow
// needs no PDF library on the n8n server.
const s = $('Settings').first().json;
const due = $('Queue bookings').all().map((i) => i.json);
const rows = $input.all().map((i) => i.json).filter((r) => r && r.Id);
const OPEN = ['Confirmed', 'WaitingConfirmation'];
const now = Date.now();
const live = s.mode === 'live';

const fmt = (ms, opts) => new Intl.DateTimeFormat('en-US', { timeZone: s.timezone, ...opts }).format(new Date(ms));
const today = fmt(now, { year: 'numeric', month: '2-digit', day: '2-digit' }).replace(/(\d+)\/(\d+)\/(\d+)/, '$3-$1-$2');

// ---- minimal PDF writer --------------------------------------------------------------
const ASCII = { '‘': "'", '’': "'", '“': '"', '”': '"', '–': '-', '—': '-', '…': '...' };
const pdfText = (v) => String(v == null ? '' : v)
  .replace(/[‘’“”–—…]/g, (c) => ASCII[c])
  .replace(/[^\x20-\x7E\xA0-\xFF]/g, '?')
  .replace(/[\\()]/g, (c) => '\\' + c);
const clip = (v, n) => { const t = String(v == null ? '' : v); return t.length > n ? t.slice(0, n - 3) + '...' : t; };

function makePdf(pages) {
  // pages: array of content-stream strings. Objects: 1 catalog, 2 pages, 3 Helvetica,
  // 4 Helvetica-Bold, then a page object and a content stream per page.
  const objs = [];
  const kids = pages.map((_, i) => `${5 + i * 2} 0 R`).join(' ');
  objs.push('<< /Type /Catalog /Pages 2 0 R >>');
  objs.push(`<< /Type /Pages /Kids [${kids}] /Count ${pages.length} >>`);
  objs.push('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>');
  objs.push('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>');
  pages.forEach((content, i) => {
    objs.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ${6 + i * 2} 0 R >>`);
    objs.push(`<< /Length ${content.length} >>\nstream\n${content}\nendstream`);
  });
  let out = '%PDF-1.4\n%\xE2\xE3\xCF\xD3\n';
  const offsets = objs.map((o, i) => { const at = out.length; out += `${i + 1} 0 obj\n${o}\nendobj\n`; return at; });
  const xref = out.length;
  out += `xref\n0 ${objs.length + 1}\n0000000000 65535 f \n`;
  out += offsets.map((o) => `${String(o).padStart(10, '0')} 00000 n \n`).join('');
  out += `trailer\n<< /Size ${objs.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`;
  return Buffer.from(out, 'latin1'); // every character above is a single byte
}

const text = (x, y, size, str, bold) => `BT /${bold ? 'F2' : 'F1'} ${size} Tf ${x} ${y} Td (${pdfText(str)}) Tj ET\n`;
const rule = (y) => `0.8 G 0.5 w 50 ${y} m 562 ${y} l S\n`;
const COLS = [[50, 'Date', 19], [150, 'Time', 10], [212, 'Visit', 33], [380, 'With', 21], [490, 'Location', 14]];

function schedulePdf(c, appts) {
  const pages = [];
  let page = '';
  let y = 0;
  const header = (first) => {
    y = 742;
    if (first) {
      page += text(50, y, 18, 'Upcoming appointments', true); y -= 22;
      page += text(50, y, 11, s.practiceName); y -= 16;
      page += text(50, y, 11, `Patient: ${c.name}`); y -= 16;
      page += text(50, y, 9, `Prepared ${fmt(now, { month: 'long', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' })}`); y -= 28;
    }
    COLS.forEach(([x, label]) => { page += text(x, y, 10, label, true); });
    y -= 6; page += rule(y); y -= 16;
  };
  header(true);
  for (const a of appts) {
    if (y < 90) { pages.push(page); page = ''; header(false); }
    const visit = a.ServiceName + (a.Status === 'WaitingConfirmation' ? ' (pending)' : '');
    const cells = [
      fmt(a.StartDate, { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' }),
      fmt(a.StartDate, { hour: 'numeric', minute: '2-digit' }),
      visit, a.PractitionerName, a.LocationName,
    ];
    COLS.forEach(([x, , n], i) => { page += text(x, y, 10, clip(cells[i], n)); });
    y -= 6; page += rule(y); y -= 16;
  }
  y -= 10;
  if (y < 60) { pages.push(page); page = ''; y = 742; }
  page += text(50, y, 10, `${appts.length} upcoming appointment${appts.length === 1 ? '' : 's'}. If anything looks wrong, please call us at ${s.practicePhone}.`);
  pages.push(page);
  return makePdf(pages);
}

// ---- one PDF per due client ----------------------------------------------------------
const out = [];
for (const c of due) {
  // The PracticeQ "client" filter is a partial name/email match, so keep only this client's rows.
  const seen = new Set();
  const appts = rows
    .filter((r) => String(r.ClientId) === String(c.clientId) && OPEN.includes(r.Status) && Number(r.StartDate) > now)
    .filter((r) => !seen.has(r.Id) && seen.add(r.Id))
    .sort((a, b) => a.StartDate - b.StartDate);
  if (!appts.length) continue; // everything was cancelled during the wait

  const uploadTo = live ? c.clientId : s.testClientId;
  if (!uploadTo) continue;
  // Earlier summaries for the same patient share the prefix and are replaced after upload.
  const filePrefix = `${live ? '' : `TEST - ${String(c.name).replace(/[\\/:*?"<>|]/g, '')} - `}Upcoming appointments `;
  const fileName = `${filePrefix}${today}.pdf`;
  out.push({
    json: { ...c, uploadTo, count: appts.length, fileName, filePrefix },
    binary: { data: { data: schedulePdf(c, appts).toString('base64'), mimeType: 'application/pdf', fileName, fileExtension: 'pdf' } },
  });
}
return out;

// Code node "Record results" (run once for all items).
// Reads the PracticeQ upload responses, one per "Build PDFs" item in the same order (the
// upload node continues on error, so a failure is an item with an `error` field).
// A failed upload is retried 10 minutes later, up to 3 attempts in total. Output is a log line
// per PDF, visible in the n8n execution.
const state = $getWorkflowStaticData('global');
state.pending = state.pending || {};
const pdfs = $('Build PDFs').all().map((i) => i.json);
const results = $('Upload to client file').all().map((i) => i.json);
const MAX_ATTEMPTS = 3;

return pdfs.map((c, i) => {
  const r = results[i] || { error: 'no response' };
  const base = { clientId: c.clientId, uploadedTo: c.uploadTo, file: c.fileName, appointments: c.count };
  if (!r.error) return { json: { ...base, status: 'uploaded', fileId: r.Id || null } };

  const attempts = (c.attempts || 0) + 1;
  const key = String(c.clientId);
  const retry = attempts < MAX_ATTEMPTS;
  if (retry && !state.pending[key]) {
    state.pending[key] = { clientId: c.clientId, email: c.email, name: c.name, dueAt: Date.now() + 10 * 60000, attempts };
  }
  const error = typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error));
  return { json: { ...base, status: retry ? 'failed, will retry' : 'failed, gave up', attempts, error } };
});

// Code node "Pick old summaries" (run once for all items).
// For each PDF that uploaded successfully, picks the patient's earlier summary PDFs (same
// name apart from the date) for deletion. Nothing is deleted when the upload failed or the
// file list could not be read, so a patient always keeps at least one summary.
const pdfs = $('Build PDFs').all().map((i) => i.json);
const uploads = $('Upload to client file').all().map((i) => i.json);
const lists = $('List client files').all().map((i) => i.json);
const escape = (t) => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

const out = [];
pdfs.forEach((c, i) => {
  const up = uploads[i] || {};
  const list = lists[i] || {};
  if (up.error || !up.Id || list.error) return;
  let files;
  try {
    files = typeof list.body === 'string' ? JSON.parse(list.body) : list.body;
  } catch (e) {
    return;
  }
  if (!Array.isArray(files)) return;
  const ours = new RegExp(`^${escape(c.filePrefix)}\\d{4}-\\d{2}-\\d{2}\\.pdf$`);
  for (const f of files) {
    if (f && f.Id && f.Id !== up.Id && ours.test(f.FileName || '')) {
      out.push({ json: { clientId: c.uploadTo, fileId: f.Id, fileName: f.FileName } });
    }
  }
});
return out;
